function factCards(g){const facts=matchupFacts(g);return facts.length?facts.map((f,i)=>`<div class="factcard"><div class="factnumber">${String(i+1).padStart(2,'0')}</div><div><div class="eyebrow">${esc(f.kind)}</div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><small>${esc(f.scope)}</small><div class="factsources">${f.sources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.label)} ↗</a>`).join('')}</div></div></div>`).join(''):'<div class="empty">No sufficiently supported oddity found for this matchup in the loaded data. Coach and player trivia is shown only where verified.</div>'}
function archiveGame(){const home=$('historyA').value,away=$('historyB').value;return {id:'archive',home,away,date:'2026-10-21T00:00:00Z',venue:$('archiveVenue').value||'All venues'}}
function refreshArchive(resetVenue=false){if($('historyA').value===$('historyB').value){$('archiveSummary').innerHTML='<div class="empty">Choose two different teams.</div>';$('archiveTable').innerHTML='';$('archiveNote').textContent='';$('archiveFacts').innerHTML='';return}let g=archiveGame();const rows=meetings(g);if(resetVenue){const venues=[...new Set(rows.map(r=>r.venue))].sort();$('archiveVenue').innerHTML='<option value="">All stadiums</option>'+venues.map(v=>`<option>${esc(v)}</option>`).join('');$('archiveVenue').value='';g=archiveGame()}historyReport(g,'archive',$('archiveVenue').value?'venue':'all');$('archiveFacts').innerHTML=factCards(g)}
function openArchive(f){const g=game(f);$('historyA').value=g.home;$('historyB').value=g.away;refreshArchive(true);tab('archive');window.scrollTo({top:200,behavior:'smooth'})}
function fillGames(){const c=$('matchConference').value||'all',fs=M.forecasts.filter(f=>c==='all'||[D.teams[game(f).home].conference,D.teams[game(f).away].conference].includes(c));let groups={};for(const f of fs){const g=game(f),key=c==='all'?groupOf(g):c;(groups[key]??=[]).push(f)}$('game').innerHTML=Object.entries(groups).sort((a,b)=>confOrder.indexOf(a[0])-confOrder.indexOf(b[0])).map(([c,fs])=>`<optgroup label="${esc(shortConf(c))}">${fs.sort((a,b)=>game(a).date.localeCompare(game(b).date)).map(f=>{const g=game(f);return `<option value="${esc(f.id)}">${esc(name(g.away))} at ${esc(name(g.home))} · ${esc(date(g))}</option>`}).join('')}</optgroup>`).join('');return fs}

function game(f){return D.games.find(g=>g.id===f.id)}
function meta(g){return B?.games[g.id]||{channels:[],homeSpread:null}}
function date(g){const m=meta(g),value=m.date||g.date,valid=m.timeValid??g.timeValid;return new Date(value).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',...(valid?{hour:'numeric',minute:'2-digit'}:{})})+(valid?' ET':' · Time TBA')}
function channel(g){const m=meta(g);return m.channels?.length?m.channels.join(' / '):'TV / streaming TBA'}
function line(g){const m=meta(g);if(m.homeSpread===null||m.homeSpread===undefined)return 'Spread not posted';if(m.homeSpread===0)return 'Pick’em';return `${name(m.homeSpread<0?g.home:g.away)} −${fmt(Math.abs(m.homeSpread),1)}`}
function modelLine(f){const g=game(f),q=forecast(f);return Math.abs(q.margin)<.05?'Pick’em':`${name(q.margin>0?g.home:g.away)} −${fmt(Math.abs(q.margin),1)}`}
function upsetInfo(f){const g=game(f),q=forecast(f),m=meta(g),posted=Number.isFinite(m.homeSpread),pickem=posted&&m.homeSpread===0;const home=posted&&!pickem?m.homeSpread>0:q.margin<0;const p=home?q.p:1-q.p;return {p:!posted||pickem?null:p,home,team:home?g.home:g.away,favorite:home?g.away:g.home,market:posted&&!pickem,pickem,label:!posted?'No posted line · upset chance unavailable':pickem?'Pick’em · no underdog':p>.5?'Model favors the upset':p>=.35?'Elevated upset risk':p>=.2?'Live upset possibility':'Lower upset risk',basis:posted?'Sportsbook underdog · outright win':'No market underdog established'}}
function meter(f,compact=false){const u=upsetInfo(f),p=u.p;return `<div class="upsetmeter ${compact?'compact':''}"><div class="meterheading"><span>${compact?esc(name(u.team))+' win chance':'UPSET METER'}</span><b>${p===null?'—':pct(p)}</b></div><div class="metertrack" role="meter" aria-label="${esc(u.pickem?'No market underdog':name(u.team)+' modeled win probability')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p===null?0:Math.round(p*100)}"><i style="width:${p===null?0:Math.round(p*100)}%"></i></div>${compact?'':`<div class="meterticks"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><b class="meterlabel">${esc(u.label)}</b><p>${!u.market?'No sportsbook underdog is established. Upset probability is unavailable.':`${esc(name(u.team))} · ${esc(u.basis)}. The meter is the model’s win probability, not a confidence grade.`}</p>`}</div>`}

function evidence(f){if(!upsetInfo(f).market)return {items:[{tag:'NO MARKET UNDERDOG',title:'No upset classification',text:'An upset means the sportsbook underdog wins outright. A missing spread or pick’em cannot establish an underdog.'}],count:0,label:'No upset classification',under:'Neither team',fav:'Neither team'};const g=game(f),q=forecast(f),ui=upsetInfo(f),underHome=ui.home,u=underHome?f.homeProfile:f.awayProfile,v=underHome?f.awayProfile:f.homeProfile,un=name(underHome?g.home:g.away),fav=name(underHome?g.away:g.home);let out=[];let families=new Set();
 if(ui.p!==null&&ui.p>=.3){families.add('baseline');out.push({tag:'COMPETITIVE BASELINE',title:`${un} is within striking distance`,text:`The core model gives ${un} a ${pct(ui.p)} win probability. The model projects it to ${((underHome?q.margin:-q.margin)>0)?'win':'lose'} by ${fmt(Math.abs(q.margin))} points. ${ui.market?'It is the market underdog.':'No market line is available, so this uses the model underdog.'}`})}
 if(u.plays>=80&&v.plays>=80&&u.net>v.net){families.add('efficiency');out.push({tag:'MEASURED EFFICIENCY',title:`The underdog owns the net success-rate edge`,text:`${un}: ${sg(u.net*100)} percentage points; ${fav}: ${sg(v.net*100)}. That is a repeatability signal, though these rates are not individually opponent-adjusted.`})}
 else if(u.plays>=80&&v.plays>=80&&u.exp>v.exp+.015){families.add('efficiency');out.push({tag:'EXPLOSIVE PLAY PATH',title:`${un} has a big-play route to an upset`,text:`Gains of 20+ yards: ${pct(u.exp)} of eligible plays versus ${pct(v.exp)} for ${fav}. Explosiveness and success rate belong to the same evidence family.`})}
 const diff=f.features[5]*(underHome?1:-1);const post=f.features[9]*(underHome?-1:1),look=f.features[10]*(underHome?-1:1);
 if(diff>2||post>0||look>0){families.add('situation');let reasons=[];if(diff>2)reasons.push(`home/road results point toward ${un}, even after adjusting for opponent strength and small samples`);if(post>0)reasons.push(`${fav} is coming off a win against a highly rated opponent`);if(look>0)reasons.push(`${fav} has a substantially stronger opponent scheduled within 14 days`);out.push({tag:'EXPERIMENTAL SCHEDULE / VENUE',title:`Context deserves a closer look`,text:reasons.join('; ')+'. These flags do not prove distraction or a letdown and are not added to the core score.'})}
 const series=f.features[12]*(underHome?1:-1);
 if(f.series.length>=2&&series>1){families.add('series');out.push({tag:'SMALL-SAMPLE SERIES',title:`Recent meetings were tougher than the rating gap suggested`,text:`Across ${f.series.length} loaded prior meetings, ${un} performed better against this opponent than the team-strength ratings suggested. This model feature uses 2025–26; the history table extends to 2016; coaching and personnel continuity are not verified.`})}
 if(!out.length)out.push({tag:'NO STRONG ALIGNMENT',title:'The loaded factors do not establish an upset storm',text:'That does not rule out an upset. It means the available efficiency, baseline, schedule and short series history do not align under the explicit warning rules.'});
 const fu=q.margin>=0?f.homeProfile:f.awayProfile,wu=q.margin>=0?f.awayProfile:f.homeProfile;
 if(q.blow>=.4)out.push({tag:'SEPARATION RISK',title:'A 21+ point result is a meaningful part of the range',text:`The core margin distribution assigns ${pct(q.blow)} to a 21+ point win by either side. ${name(q.margin>=0?g.home:g.away)} has an expected advantage of ${fmt(Math.abs(q.margin))} points; ${fu.net>wu.net?'its net success-rate advantage supports a repeatable efficiency path.':'efficiency evidence is mixed, so the large-margin tail should not be treated as certainty.'}`});
 return {items:out,count:families.size,label:ui.pickem?'Pick’em matchup':families.size>=3?'Multiple upset signals':families.size===2?'Upset watch':q.blow>=.5?'Separation watch':'Mixed evidence',under:un,fav}}
function splitText(p){return p.n?`${p.wins}–${p.n-p.wins} · ${p.ppg} scored / ${p.allowed} allowed (${p.n} games)`:'No completed games in this split'}
function row(label,a,h){return `<tr><td>${esc(label)}</td><td>${esc(a)}</td><td>${esc(h)}</td></tr>`}
function show(id){const f=M.forecasts.find(x=>x.id===id);if(!f)return;current=f;renderSituationalMatch(f);if(typeof renderUpgradeMatch==='function')renderUpgradeMatch(f);if(typeof renderMatchupContext==='function')renderMatchupContext(f);const g=game(f),q=forecast(f),e=evidence(f),a=f.awayProfile,h=f.homeProfile,ui=upsetInfo(f);$('game').value=id;historyFilter='all';historyReport();$('oddities').innerHTML=factCards(g);$('awayLogo').innerHTML=logo(g.away);$('homeLogo').innerHTML=logo(g.home);$('scoreNote').textContent=q.adjusted?'One-point display tiebreak applied to the model favorite; probability unchanged.':'';
 $('matchTitle').textContent=`${name(g.away)} at ${name(g.home)}`;$('kickoff').textContent=date(g);$('venue').textContent=`${g.venue}${g.neutral?' · Neutral site':''} · ${channel(g)}`;$('matchMeter').innerHTML=meter(f);$('similarUpsets').innerHTML=similarUpsets(f);$('marketInfo').innerHTML=`<div><small>SPORTSBOOK SPREAD</small><b>${esc(line(g))}</b></div><div><small>MODEL SPREAD</small><b>${esc(modelLine(f))}</b></div><p>${meta(g).provider?esc(meta(g).provider)+' via ESPN · ':''}Retrieved ${meta(g).retrievedAt?new Date(meta(g).retrievedAt).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET':'time unavailable'}. Snapshot, not live odds.</p>`;$('label').textContent=e.label;$('headline').textContent=e.count>=3?`Several warning signs point toward ${e.under}.`:ui.market&&ui.p>.5?`The model calls for a ${name(ui.team)} upset.`:q.blow>=.5?`${name(q.margin>=0?g.home:g.away)} has a path to separation.`:`The margin tells the story.`;
 $('verdict').textContent=`${name(q.margin>=0?g.home:g.away)} leads the main forecast by ${fmt(Math.abs(q.margin))} points. ${ui.pickem?'The market is pick’em, so there is no market underdog.':`${name(ui.team)} has a ${pct(ui.p)} modeled win chance as the ${ui.market?'market':'model'} underdog.`} ${e.count>=3?'Warning signs align across different types of evidence.':'See which warning signs align below.'} Missing availability and QB information limits the assessment.`;
 $('stormcount').textContent=e.count+' / 4';$('signals').innerHTML=e.items.map(s=>`<div class="signal"><span class="tag">${esc(s.tag)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div>`).join('');
 $('an').textContent=name(g.away);$('hn').textContent=name(g.home);$('as').textContent=q.a;$('hs').textContent=q.h;$('ap').textContent=`${D.teams[g.away].abbr} ${pct(1-q.p)}`;$('hp').textContent=`${D.teams[g.home].abbr} ${pct(q.p)}`;$('bar').style.width=pct(1-q.p);$('upset').textContent=ui.p===null?'Pick’em':pct(ui.p);$('blowout').textContent=pct(q.blow);
 $('range').textContent=`The model’s estimated 80% range stretches from ${pickText(g,q.margin-1.282*f.coreSd)} to ${pickText(g,q.margin+1.282*f.coreSd)}. That wide range shows how uncertain one game can be; it is not a guarantee.`;
 $('edge').textContent=`With extra situational factors: ${pickText(g,f.margin)}. That version has been less accurate on point differences in our test, so it does not replace the main pick.`;
 const rate=(v,n)=>n>=1?pct(v):'Unavailable';
 let ranks={};for(const ff of M.forecasts){const gg=game(ff);for(const [id,p] of [[gg.home,ff.homeProfile],[gg.away,ff.awayProfile]])if(D.teams[id].conference!=='Non-FBS opponent'&&p.record.n)ranks[id]=p}
 const rank=(id,key,asc=false)=>{const arr=Object.entries(ranks).sort((x,y)=>(asc?1:-1)*(x[1].record[key]-y[1].record[key]));const i=arr.findIndex(x=>x[0]===id);return i<0?'N/A':`${i+1} / ${arr.length}`};
 $('comparison').innerHTML=`<tr><th>Metric</th><th>${esc(name(g.away))}</th><th>${esc(name(g.home))}</th></tr>`+row('2026 record',`${a.record.wins}–${a.record.n-a.record.wins}`,`${h.record.wins}–${h.record.n-h.record.wins}`)+row('Points per game',a.record.ppg,h.record.ppg)+row('Points allowed per game',a.record.allowed,h.record.allowed)+row('Scoring offense rank · slate teams',rank(g.away,'ppg'),rank(g.home,'ppg'))+row('Scoring defense rank · slate teams',rank(g.away,'allowed',true),rank(g.home,'allowed',true))+row('Offense: plays that kept the drive on track',rate(a.sr,a.plays),rate(h.sr,h.plays))+row('Defense: opponent plays that stayed on track',rate(a.dsr,a.dplays),rate(h.dsr,h.dplays))+row('Successful-play advantage',a.plays&&a.dplays?sg(100*a.net)+' pp':'Unavailable',h.plays&&h.dplays?sg(100*h.net)+' pp':'Unavailable')+row('Big plays: gains of 20+ yards',rate(a.exp,a.plays),rate(h.exp,h.plays))+row('Offensive plays used in these stats',a.plays,h.plays)+row('Total offensive yards / game',fmt(a.yards),fmt(h.yards))+row('Team strength rating',fmt(a.elo,0),fmt(h.elo,0));
 const ct=(title,txt)=>`<div class="contextrow"><b>${esc(title)}</b><p>${esc(txt)}</p></div>`;
 $('contextReport').innerHTML=ct(`${name(g.away)} on the road`,splitText(a.away))+ct(`${name(g.home)} at home`,splitText(h.home))+ct('Evening kickoffs · 7 p.m. ET or later',`${name(g.away)}: ${splitText(a.night)}. ${name(g.home)}: ${splitText(h.night)}.`)+ct('Games immediately after a defined big win',`${name(g.away)}: ${splitText(a.afterBig)}. ${name(g.home)}: ${splitText(h.afterBig)}. A big win means beating an opponent with a high pregame team-strength rating.`)+ct('Last completed game',`${name(g.away)}: ${a.last?`${a.last.pf}–${a.last.pa} vs ${name(a.last.opp)} on ${a.last.date.slice(0,10)}`:'Unavailable'}. ${name(g.home)}: ${h.last?`${h.last.pf}–${h.last.pa} vs ${name(h.last.opp)} on ${h.last.date.slice(0,10)}`:'Unavailable'}.`)+ct('Specific-stadium history',`Open the Rivalry File above to see actual ${name(g.away)}–${name(g.home)} meetings in ${g.venue}, with dates, final scores and source links. Historical patterns span different coaches and rosters, so they are not automatic prediction adjustments.`);
 const driverLabels={'Elo difference':'Strength based on previous results','Net success-rate difference':'Ability to keep drives moving','Scoring margin difference':'Recent scoring performance','Scoring environment':'How much these teams usually score','Home field':'Playing at home','Explosive-rate difference':'Big-play ability','Yards/game difference':'Offensive yardage'};
 $('driverSummary').innerHTML=[...f.coreContributions].sort((a,b)=>Math.abs(b.points)-Math.abs(a.points)).slice(0,3).map(r=>`<p><b>${esc(driverLabels[r.name]||r.name)}</b><span>Moves the forecast ${fmt(Math.abs(r.points),1)} points toward ${esc(name(r.points>=0?g.home:g.away))}.</span></p>`).join('');
 $('drivers').innerHTML=[{name:'Intercept',points:f.coreIntercept},...f.coreContributions.sort((a,b)=>Math.abs(b.points)-Math.abs(a.points))].map(r=>`<div class="driver"><span>${esc(r.name)}</span><b>${sg(r.points)}</b></div>`).join('');
 $('sources').innerHTML=`<a href="${esc(g.url)}" target="_blank" rel="noreferrer">Game schedule / source ↗</a><a href="https://www.espn.com/college-football/team/schedule/_/id/${encodeURIComponent(g.away)}" target="_blank" rel="noreferrer">${esc(name(g.away))} game history ↗</a><a href="https://www.espn.com/college-football/team/schedule/_/id/${encodeURIComponent(g.home)}" target="_blank" rel="noreferrer">${esc(name(g.home))} game history ↗</a><p class="tiny">${a.plays} away-team and ${h.plays} home-team eligible offensive plays loaded.${f.limited?' LIMITED PLAY COVERAGE: advanced features rely substantially on a league prior.':''}</p>`;
}
function tab(id){document.querySelectorAll('.tab').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id))}
function gameCard(f,rank=0){const g=game(f),q=forecast(f),e=evidence(f),u=upsetInfo(f);return `<button class="gamecard ${rank?'spotlightcard':''}" data-game="${esc(f.id)}">${rank?`<div class="spotlightrank">#${rank} <span>${e.count} TYPES OF WARNING SIGNS · ${esc(name(u.team))} UPSET WATCH</span></div>`:''}<div class="cardtop"><span>${esc(date(g))}</span><span class="signalbadge ${e.count>=2?'watch':''}">${esc(e.label)}</span></div><div class="broadcastline"><span>WATCH</span> ${esc(channel(g))}</div><div class="cardteam">${logo(g.away)}<span>${esc(name(g.away))}<small>${esc(shortConf(D.teams[g.away].conference))}</small></span><strong>${q.a}</strong></div><div class="cardteam">${logo(g.home)}<span>${esc(name(g.home))}<small>${esc(shortConf(D.teams[g.home].conference))} · HOME</small></span><strong>${q.h}</strong></div><div class="spreadrow"><span>MARKET <b>${esc(line(g))}</b></span><span>MODEL <b>${esc(modelLine(f))}</b></span></div>${meter(f,true)}<div class="cardbottom"><span>${u.pickem?'No market underdog':esc(u.basis)}</span><span><b>${pct(q.blow)}</b> 21+ point win</span><span class="historyshortcut" data-history-game="${esc(f.id)}">HISTORY ↗</span><em>REPORT ↗</em></div></button>`}
function radar(){const conference=$('conference').value||'all',week=$('week').value||'this',query=($('search').value||'').trim().toLowerCase();let fs=M.forecasts.filter(f=>{const g=game(f),day=(meta(g).date||g.date).slice(0,10);return (conference==='all'||[D.teams[g.home].conference,D.teams[g.away].conference].includes(conference))&&(week==='all'||(week==='this'?day<='2026-10-26':day>='2026-10-27'))&&(!query||[name(g.home),name(g.away),D.teams[g.home].abbr,D.teams[g.away].abbr].some(n=>n.toLowerCase().includes(query)))});const sort=$('sort').value;fs.sort((a,b)=>sort==='date'?game(a).date.localeCompare(game(b).date):sort==='storm'?evidence(b).count-evidence(a).count:sort==='blowout'?forecast(b).blow-forecast(a).blow:(upsetInfo(b).p??-1)-(upsetInfo(a).p??-1));const groups={};for(const f of fs){const key=conference==='all'?groupOf(game(f)):conference;(groups[key]??=[]).push(f)}
 $('boardStats').innerHTML=`<div><b>${fs.length}</b><span>matchups</span></div><div><b>${fs.filter(f=>evidence(f).count>=2).length}</b><span>upset-watch games</span></div><div><b>${fs.filter(f=>forecast(f).blow>=.5).length}</b><span>separation-watch games</span></div>`;
 const top=fs.filter(f=>upsetInfo(f).market&&evidence(f).count>=1).sort((a,b)=>evidence(b).count-evidence(a).count||upsetInfo(b).p-upsetInfo(a).p).slice(0,3);$('spotlightTitle').textContent=week==='this'?'Top upset signals this week':week==='next'?'Top upset signals · Oct 27–Nov 1':'Top upset signals · loaded slate';$('spotlight').innerHTML=top.length?top.map((f,i)=>gameCard(f,i+1)).join(''):'<div class="empty">No qualifying games with a posted market underdog in this selection.</div>';
 $('radar').innerHTML=fs.length?Object.entries(groups).sort((a,b)=>confOrder.indexOf(a[0])-confOrder.indexOf(b[0])).map(([c,fs])=>`<section class="conferencegroup"><div class="conferenceheading"><h3>${esc(shortConf(c))}</h3><span>${fs.length} GAMES</span></div><div class="gamegrid">${fs.map(f=>gameCard(f)).join('')}</div></section>`).join(''):'<div class="empty">No games match these filters. Try another conference or schedule window.</div>';
 $('oddsTimestamp').textContent=`Odds and TV listings retrieved ${new Date(B.retrievedAt).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} ET. Spreads can change; unavailable lines and channels are marked TBA. Kickoffs are Eastern time.`;
 document.querySelectorAll('[data-conference]').forEach(b=>b.classList.toggle('active',b.dataset.conference===conference));}


function upsetBand(p){return U.bands.find(b=>p>=b.lo&&(p<b.hi||b.hi===1&&p===1))}
function upsetRecord(r){return `${r.wins}–${r.losses}`}
function cohortGames(r){return `<details class="technical"><summary>See the ${r.n} games</summary><div class="cohortgames">${r.ids.map(id=>{const x=U.rows.find(x=>x.id===id);return `<a href="${esc(x.url)}" target="_blank" rel="noreferrer"><span>${esc(name(x.team))} vs ${esc(name(x.opponent))}<small>${new Date(x.date).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'})} · ${pct(x.p)} estimated chance · ${esc(x.provider)} closing line</small></span><b>${x.won?'WON':'LOST'}</b></a>`}).join('')}</div></details>`}
function sampleNote(r){return !r.n?'No matching games':r.n<5?'Too few games to judge':r.n<30?'Small sample · early evidence':'Exploratory · needs more seasons'}
function currentFlags(f){const u=upsetInfo(f),g=game(f),sign=u.team===g.home?1:-1;return [sign===1&&!g.neutral?'home':null,sign*f.features[1]>0?'efficiency':null,-sign*f.features[9]>0?'bigwin':null,-sign*f.features[10]>0?'lookahead':null].filter(Boolean)}
function patternCard(r){return `<div class="patterncard"><span class="tag">${sampleNote(r)}</span><h3>${esc(r.label)}</h3><strong>${upsetRecord(r)} <small>underdog record</small></strong><p>${r.n?`${r.wins} wins in ${r.n} games (${pct(r.rate)}). The model expected about ${fmt(r.expected)} wins.`:'No examples in this test.'}</p><p class="tiny">Earlier games: ${upsetRecord(r.earlier)} · Later games: ${upsetRecord(r.later)}. These are exploratory splits, not independent validation.</p>${r.n?cohortGames(r):''}</div>`}
function similarUpsets(f){const u=upsetInfo(f);if(!u.market||u.p===null)return '<div class="similarbox"><h3>What happened in similar games?</h3><p>A posted sportsbook underdog is needed to make this comparison. Pick’em and model-only underdogs are not mixed into the historical sportsbook records.</p></div>';const b=upsetBand(u.p),flags=currentFlags(f),matched=U.patterns.filter(r=>r.n&&r.keys.every(k=>flags.includes(k))).sort((a,b)=>b.keys.length-a.keys.length||b.n-a.n);return `<div class="similarbox"><span class="eyebrow">HISTORY BEHIND THE METER</span><h3>Underdogs with a ${b.label} chance</h3><div class="cohortscore">${upsetRecord(b)} <small>historical record</small></div><p>${b.n?`They won <b>${b.wins} of ${b.n}</b> games (${pct(b.rate)}). The model expected about ${fmt(b.expected)} wins.`:'No games fell in this range in our test.'}</p><p class="tiny">${sampleNote(b)}. Similar chance does not mean identical teams or circumstances. This record does not replace today’s ${pct(u.p)} estimate.</p>${b.n?cohortGames(b):''}${matched.length?`<details class="technical"><summary>Matching situations for this game</summary>${matched.map(patternCard).join('')}</details>`:'<p class="tiny">No tested situational group matches this game with recorded results.</p>'}<p class="tiny">Past-game replay · archived closing spreads · Sep 26–Oct 17, 2026 (ET). Not live-issued picks.</p></div>`}
function upsetHistory(){const perfect=U.patterns.filter(r=>r.n>=5&&r.losses===0),tiny=U.patterns.filter(r=>r.n>0&&r.n<5&&r.losses===0);$('upsetHistory').innerHTML=`<div class="eyebrow">DOES THE UPSET METER HOLD UP?</div><h2>How often did the underdogs actually win?</h2><p>${U.rows.length} past games with ESPN-reported closing spreads, out of ${U.testedGames} tested games. Each game appears once per probability range. A win means winning the game outright.</p><div class="notice"><b>${perfect.length?`${perfect.length} undefeated situations with at least five games`:'No undefeated situations with five or more games'}</b><p>We checked ${U.patterns.length} fixed situations: four individual factors and their six two-factor combinations. ${tiny.length?tiny.map(r=>`${esc(r.label)} was ${upsetRecord(r)}—only ${r.n} game${r.n===1?'':'s'}.`).join(' '):''} An undefeated past record is never a guaranteed future win.</p></div><div class="tablewrap"><table class="upsetbands"><thead><tr><th>Upset meter range</th><th>Underdog record</th><th>Actual win rate</th><th>Model expected</th></tr></thead><tbody>${U.bands.map(b=>`<tr><td>${b.label}</td><td>${upsetRecord(b)} <small>(${b.n} games)</small></td><td>${b.n?pct(b.rate):'No games'}</td><td>${b.n?fmt(b.expected)+' wins':'—'}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Ranges include the lower boundary and exclude the upper boundary; the last includes 100%. Above 50% means the model favored the sportsbook underdog. Empty ranges are not evidence.</p><details class="technical"><summary>Explore all ${U.patterns.length} situations and their games</summary><div class="patterngrid">${U.patterns.map(patternCard).join('')}</div></details><details class="technical"><summary>How to read this evidence</summary><p>Earlier games are before October 11 UTC; later games are on or after that date. We show both periods for every situation, including losing records. No situation was independently validated on a new season, and overlapping groups are not independent evidence.</p><p>“Big win” means beating an opponent rated at least 1600 before the game—not necessarily a ranked opponent. “Stronger opponent coming up” means an opponent rated over 100 points higher within 14 days. Successful-play advantage compares offense minus defense success rates before the game. Home excludes neutral sites.</p><p>Historical probabilities use the main model’s earlier-date fit and uncertainty estimate at each test date. Current forecasts use a later fit and an updated uncertainty estimate, so this is an exploratory comparison, not a calibrated replacement probability. Injuries, QB experience and ranked-opponent/night combinations are not tested here.</p><p>Source: ESPN game summaries, explicitly labeled home and away closing lines. These archives were retrieved after the games; forecasts are reconstructions, not published pregame picks. ${U.excluded.length} games excluded for missing closing spreads or pick’em. Historical patterns do not change the scores or upset meter.</p></details>`}

function pickText(g,margin,actual=false){if(Math.abs(margin)<.000001)return actual?'Finished tied':'Too close to call';const team=name(margin>0?g.home:g.away),points=Math.abs(margin),amount=actual?fmt(points,0):(points<1?'less than 1':`about ${Math.round(points)}`);return `${team} ${actual?'won':'to win'} by ${amount} ${actual&&points===1?'point':'points'}`}
function validation(){upsetHistory();const n=M.heldout.length,wins=M.heldout.filter(r=>r.core[0]!==0&&Math.sign(r.core[0])===Math.sign(r.actual[0])).length;
 $('testIntro').textContent=`We replayed ${n} past games using only information from earlier dates. This shows how the model would have performed—not picks published before kickoff.`;
 $('testSummary').innerHTML=`<div class="plainstat"><small>WINNERS PICKED CORRECTLY</small><b>${wins} <span>of ${n}</span></b><p>About ${Math.round(100*wins/n)} out of every 100 games in this test.</p></div><div class="plainstat"><small>AVERAGE MISS ON WINNING MARGIN</small><b>${fmt(M.core.marginMAE,1)} <span>points</span></b><p>The average gap between the predicted and actual point difference, including games where the winner was wrong.</p></div>`;
 const rows=[['Picked the winning team','accuracy',true],['Average error in the point difference · lower is better','marginMAE',false],['Average error in combined points · lower is better','totalMAE',false],['Probability error (Brier score) · lower is better','brier',false],['Games inside the estimated 80% range','coverage80',true]];
 $('metrics').innerHTML='<tr><th>Measure</th><th>Main model</th><th>With extra situational factors</th></tr>'+rows.map(([label,k,p])=>row(label,p?pct(M.core[k]):fmt(M.core[k],k==='brier'?3:1),p?pct(M.full[k]):fmt(M.full[k],k==='brier'?3:1))).join('');
 $('modelFinding').textContent=`Adding the extra situational factors increased the average point-difference error from ${fmt(M.core.marginMAE,1)} to ${fmt(M.full.marginMAE,1)} points. That is why the simpler model still provides the main pick. This test covers only a few weeks; we need more games before claiming dependable accuracy.`;
 $('calibration').innerHTML='<tr><th>Home team’s predicted win chance</th><th>Games tested</th><th>Average predicted chance</th><th>How often home teams actually won</th></tr>'+M.calibration.map(r=>`<tr><td>${r.band}</td><td>${r.n}</td><td>${r.n?pct(r.predicted):'—'}</td><td>${r.n?pct(r.actual):'—'}</td></tr>`).join('');
 $('heldout').innerHTML='<thead><tr><th>Game</th><th>Model’s pick</th><th>What happened</th><th>How it did</th></tr></thead><tbody>'+M.heldout.slice(-25).reverse().map(r=>{const g=D.games.find(g=>g.id===r.id),right=r.core[0]!==0&&Math.sign(r.core[0])===Math.sign(r.actual[0]),miss=Math.abs(r.core[0]-r.actual[0]),day=new Date(g.date).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'});return `<tr><td data-label="Game"><b>${esc(name(g.away))} at ${esc(name(g.home))}</b><small>${esc(day)}</small></td><td data-label="Model’s pick">${esc(pickText(g,r.core[0]))}</td><td data-label="What happened">${esc(pickText(g,r.actual[0],true))}<small>${esc(name(g.away))} ${g.as} · ${esc(name(g.home))} ${g.hs}</small></td><td data-label="How it did"><span class="resultbadge ${right?'right':'wrong'}">${r.core[0]===0?'No winner picked':right?'Correct winner':'Wrong winner'}</span><small>Point difference off by ${fmt(miss,1)}</small></td></tr>`}).join('')+'</tbody>'}

function download(){const f=current,g=game(f),out={asOf:D.asOf,source:D.source,game:g,forecast:forecast(f),upset:upsetInfo(f),marketAndBroadcast:meta(g),evidence:evidence(f),experimentalContextMargin:f.margin,history:meetings(g),matchupResearch:typeof contextData!=='undefined'?contextData.games?.[f.id]:null,availability:typeof availabilityData!=='undefined'?availabilityData.games?.[f.id]:null,environment:typeof environmentData!=='undefined'?environmentData.games?.[f.id]:null,missing:['Confirmed starting QB and career starts','Verified motivation','Historically calibrated context effects'],modelRecord:{core:M.core,context:M.full,testedGames:M.testedGames},detail:f};const blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dart-model-${g.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function init(){try{[D,M,H,A,B,P,U]=await Promise.all(['data.json','model.json','history.json','asset-manifest.json','game-details.json','player-facts.json','upset-history.json'].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error(`Could not load ${u}`);return r.json()}));$('loading').textContent=`${Object.values(D.teams).filter(t=>t.conference!=='Non-FBS opponent').length} FBS teams · ${H.games.length.toLocaleString()} historical results · ${M.forecasts.length} matchup forecasts · October 20 snapshot`;const conf=confOrder.filter(c=>c!=='Cross-conference');const opts=conf.map(c=>`<option value="${esc(c)}">${esc(shortConf(c))}</option>`).join('');$('conference').innerHTML+=opts;$('matchConference').innerHTML+=opts;$('conferenceTabs').innerHTML=[['all','All FBS'],...conf.map(c=>[c,shortConf(c)])].map(([c,n])=>`<button data-conference="${esc(c)}" class="${c==='all'?'active':''}">${esc(n)}</button>`).join('');$('dataSummary').textContent=`${H.games.length.toLocaleString()} historical results across 2016–2026. ${H.requestedTeamSeasons} team-season schedules requested; ${H.failures.length} failed. The forecast training dataset remains 2025–26 with ${D.games.filter(g=>g.stats).length} current-season game summaries. Older results enrich the history report without an unvalidated change to forecast weights.`;$('definitions').textContent=D.advancedDefinition;const teamOptions=Object.values(D.teams).filter(t=>t.conference!=='Non-FBS opponent').sort((a,b)=>a.name.localeCompare(b.name)).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');$('historyA').innerHTML=teamOptions;$('historyB').innerHTML=teamOptions;$('historyA').value='2';$('historyB').value='99';refreshArchive(true);fillGames();show(M.forecasts.some(f=>f.id==='401856728')?'401856728':M.forecasts[0].id);radar();validation();tab('slate')}catch(e){$('loading').textContent='Data could not load. Please reload the page. '+e.message;console.error(e)}}
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));$('game').addEventListener('change',()=>show($('game').value));$('matchConference').addEventListener('change',()=>{const fs=fillGames();if(fs.length)show(fs[0].id)});for(const id of ['sort','conference','week'])$(id).addEventListener('change',radar);$('search').addEventListener('input',radar);$('conferenceTabs').addEventListener('click',e=>{const b=e.target.closest('[data-conference]');if(b){$('conference').value=b.dataset.conference;radar()}});for(const panel of ['radar','spotlight'])$(panel).addEventListener('click',e=>{const h=e.target.closest('[data-history-game]');if(h){openArchive(M.forecasts.find(f=>f.id===h.dataset.historyGame));return}const b=e.target.closest('[data-game]');if(b){$('matchConference').value='all';fillGames();show(b.dataset.game);tab('lab');window.scrollTo({top:200,behavior:'smooth'})}});document.querySelectorAll('[data-history]').forEach(b=>b.addEventListener('click',()=>{historyFilter=b.dataset.history;historyReport()}));for(const id of ['historyA','historyB'])$(id).addEventListener('change',()=>refreshArchive(true));$('archiveVenue').addEventListener('change',()=>refreshArchive());$('export').addEventListener('click',download);const initialDataReady=init();loadSituationalResearch();
